/* 설계: independent original domains and source namespaces. */
@model intersection_model { version:0; length-unit:mm;
@curve #curve_sibling { type:nurbs; degree:1; knots:[0.000,0,1,1.00]; control-points:[[-0,2,1],[3,4,2]]; weights:[1,2]; }
@surface #support { type:nurbs; degree-u:2; degree-v:1; knots-u:[-1,-1,-1,1,1,1]; knots-v:[-0.5,-0.5,1.5,1.5]; control-points:[[[-1,-0.5,1],[-1,1.5,1]],[[0,-0.5,-1],[0,1.5,-1]],[[1,-0.5,1],[1,1.5,1]]]; weights:[[1,1],[1,1],[1,1]]; }
@surface #native_wide_sibling { type:nurbs; degree-u:1; degree-v:1; knots-u:[0,0,1,1]; knots-v:[-1,-1,2,2]; control-points:[[[12000,2,-0],[12000,4,1]],[[12002,2,2],[12002,4,3]]]; weights:[[1,2],[3,4]]; }
}

